import unicodedata

def slugify(texte):
    """Transforme un texte en slug d'URL."""
    if not texte:
        return ""
    plat = unicodedata.normalize("NFKD", texte)
    return "".join(c for c in plat if not unicodedata.combining(c)).lower()

